mapper.select:
SELECT DATE(m.created_at) AS date, m.movement_type AS movementType, COUNT(*) AS movementCount, COALESCE(SUM(ABS(m.qty)), 0) AS totalQty FROM material_stock_movement m
LEFT JOIN material_request r ON m.request_id = r.id
WHERE DATE(m.created_at) BETWEEN #{from} AND #{to}
AND m.movement_type = 'OUTBOUND' AND r.applicant_group = #{groupId}
GROUP BY DATE(m.created_at), m.movement_type ORDER BY date

SELECT DAYOFWEEK(m.created_at) AS dayOfWeek, HOUR(m.created_at) AS hour, COUNT(*) AS count
FROM material_stock_movement m

    LEFT JOIN material_request r ON m.request_id = r.id

WHERE m.movement_type = 'OUTBOUND' AND DATE(m.created_at) BETWEEN #{from} AND #{to}
AND r.applicant_group = #{groupId}
GROUP BY DAYOFWEEK(m.created_at), HOUR(m.created_at)
